import re
LAYOFF=re.compile(r"\blay[- ]?offs?\b|\blaid[- ]off\b|\blaying off\b|restructur\w*|downsiz\w*|re-?org(?:s|anization|anisation)?\b|reduction in force|\brifs?\b|job cuts?|cut(?:s|ting)? (?:jobs|staff|headcount|positions|workforce|employees)|headcount (?:cuts?|reduction)|let go\b|let (?:people|employees) go|mass (?:firing|layoff)|redundanc(?:y|ies)|furlough\w*|firing (?:people|employees|staff)",re.I)
WORKLOAD=re.compile(r"understaff\w*|under-staff\w*|short[- ]?staff\w*|not enough (?:staff|people|employees|workers|manpower|hands|resources|headcount|team ?members)|lack of (?:staff|staffing|manpower|people|resources|headcount)|(?:too )?(?:few|little) (?:staff|employees|people|workers)|stretched (?:thin|too thin)|spread (?:too )?thin|work of (?:two|2|three|3|multiple|several|\d+) (?:people|persons|employees|jobs)|(?:two|2|three|3|multiple|several) (?:people'?s?|persons'?s?|jobs'? ?|roles'? ?)(?:jobs|work|roles|positions)|doing (?:the work of|more than|everything)|wear(?:ing)? (?:many|multiple|several|too many|a lot of) hats|overwork\w*|over-?worked|workloads?|too much work|(?:more|do more) with less|heavy work|hiring freeze|burn(?:ed|t)?[- ]?out|unrealistic (?:expectations|deadlines|workload)|(?:no|not enough) time to|spread across|extra duties|additional responsibilities|take on (?:more|extra) (?:work|responsibilit)\w*|constantly (?:asked|expected) to do more",re.I)
WORKLOAD_STRICT=re.compile(r"understaff\w*|under-staff\w*|short[- ]?staff\w*|not enough (?:staff|people|employees|workers|manpower|hands|headcount|team ?members)|lack of (?:staff|staffing|manpower|headcount)|(?:too )?(?:few|little) (?:staff|employees|people|workers)|stretched (?:thin|too thin)|spread (?:too )?thin|work of (?:two|2|three|3|multiple|several|\d+) (?:people|persons|employees|jobs)|doing (?:the work of|more than)|wear(?:ing)? (?:many|multiple|several|too many|a lot of) hats|(?:more|do more) with less|hiring freeze|take on (?:more|extra) (?:work|responsibilit)\w*|workloads?\b",re.I)
AUTO=re.compile(r"\bAI\b|\bA\.I\.|artificial intelligence|chat ?gpt|\bLLMs?\b|machine learning|automat(?:e|ed|ion|ing|es)\b|\brobots?\b|replaced (?:by|with) (?:ai|automation|machines|robots|bots)|\bbots?\b|self[- ]checkout|kiosks?|generative|copilot|algorithm",re.I)
OFFSHORE=re.compile(r"offshor\w*|off-shor\w*|outsourc\w*|nearshor\w*|moving (?:jobs|work|positions|roles) (?:to|overseas)|(?:jobs|work|positions|roles) (?:moved|moving|shipped|sent) (?:to|overseas)|overseas (?:team|teams|office|offices|staff|employees|workers|labor|labour|contractors|resources)|cheaper (?:labor|labour)|india(?:n)? (?:team|office|based|offshore|counterpart)s?|(?:team|office|teams) in india|replaced by (?:contractors|foreign)|foreign (?:labor|workers)",re.I)

STAFFING=re.compile(r"understaff\w*|under-staff\w*|short[- ]?staff\w*|not enough (?:staff|people|employees|workers|manpower|hands|headcount|team ?members)|lack of (?:staff|staffing|manpower|headcount)|(?:too )?(?:few|little) (?:staff|employees|people|workers)(?! skills)|stretched (?:thin|too thin)|spread (?:too )?thin|work of (?:two|2|three|3|multiple|several|\d+) (?:people|persons|employees|jobs)|doing (?:the work of|more than)|wear(?:ing)? (?:many|multiple|several|too many|a lot of) hats|(?:more|do more) with less|take on (?:more|extra) (?:work|responsibilit)\w*|(?:two|2|three|3) (?:people'?s?|jobs?|roles?|positions?)(?: worth)?|job duties keep growing|duties keep growing",re.I)
WORKLOAD_ANY=re.compile(r"workloads?\b|overwork\w*|over-?worked|too much work|heavy work|work overload|overload\w*|unmanageable|excessive work",re.I)

AI_MENTION=re.compile(r"\bAI\b|\bA\.I\.|artificial intelligence|chat ?gpt|\bLLMs?\b|machine learning|generative|copilot|automat(?:e|ed|ion|ing|es)\b",re.I)
_A=r"(?:\bAI\b|A\.I\.|artificial intelligence|chat ?gpt|\bLLMs?\b|automat(?:e|ed|ion|ing|es)\b|machine learning|robots?)"
_T=r"(?:replac\w+|taking (?:over|our|my|jobs)|take (?:over|our|my|jobs)|lose (?:my|your|our|their|the) jobs?|losing (?:my|your|our|their) jobs?|lay ?offs?|laid off|cut(?:s|ting)? (?:jobs|staff|headcount|positions|people|workforce)|eliminat\w+|redundan\w+|job (?:loss|losses|security|cuts)|obsolete|downsiz\w+|headcount|fewer (?:people|employees|staff|jobs)|\d+% cut|let go|firing|fired)"
AI_THREAT=re.compile(_A+r"[^.\n]{0,80}"+_T+r"|"+_T+r"[^.\n]{0,80}"+_A,re.I)

_O=r"(?:offshor\w*|outsourc\w*|overseas|off-shor\w*|india\w*|philippines|mexico|poland|nearshor\w*)"
_J=r"(?:jobs?|roles?|positions?|work|layoffs?|laid|replac\w+|eliminat\w+|cuts?|moving|moved|shift\w*|mass|downsiz\w+|backfills?|headcount|entire (?:teams?|departments?))"
OFFSHORE_DISPLACE=re.compile(r"(?:offshor\w*|outsourc\w*|off-shor\w*)[^.\n]{0,50}\b"+_J+r"|\b"+_J+r"[^.\n]{0,40}(?:offshor\w*|outsourc\w*|off-shor\w*|overseas|to india|to the philippines|to mexico)|constant(?:ly)? (?:offshor|outsourc)\w*|(?:more and more|lots of|heavy|too much|a lot of|so much) (?:offshor|outsourc)\w*",re.I)
